@namespace sv_47ad34a54a674fefb4a9879cc9933029.Components.Pages.ApplySteps

<nav aria-label="Application progress" class="mb-4">
    <ol class="d-flex list-unstyled justify-content-between position-relative step-indicator">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var stepIndex = i;
            var isCompleted = stepIndex < CurrentStep;
            var isCurrent = stepIndex == CurrentStep;
            var isFuture = stepIndex > CurrentStep;

            <li class="text-center flex-fill step-item @(isCurrent ? "active" : "") @(isCompleted ? "completed" : "") @(isFuture ? "dimmed" : "")">
                @if (isCompleted)
                {
                    <button type="button" class="btn btn-link p-0 text-decoration-none" @onclick="() => OnStepClicked.InvokeAsync(stepIndex)">
                        <span class="step-circle bg-success text-white">✓</span>
                        <div class="step-label text-success fw-semibold mt-1">@StepNames[stepIndex]</div>
                    </button>
                }
                else
                {
                    <div>
                        <span class="step-circle @(isCurrent ? "bg-primary text-white" : "bg-secondary text-white opacity-50")">@(stepIndex + 1)</span>
                        <div class="step-label mt-1 @(isCurrent ? "fw-semibold text-primary" : "text-muted")">@StepNames[stepIndex]</div>
                    </div>
                }
            </li>
        }
    </ol>
</nav>

@code {
    private static readonly string[] StepNames = ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    [Parameter, EditorRequired]
    public int CurrentStep { get; set; }

    [Parameter]
    public EventCallback<int> OnStepClicked { get; set; }
}

.step-indicator {
    counter-reset: step;
}

.step-circle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border-radius: 50%;
    font-size: 0.875rem;
    font-weight: 600;
}

.step-item {
    position: relative;
}

.step-item:not(:last-child)::after {
    content: '';
    position: absolute;
    top: 18px;
    left: calc(50% + 22px);
    width: calc(100% - 44px);
    height: 2px;
    background-color: #dee2e6;
}

.step-item.completed:not(:last-child)::after {
    background-color: #198754;
}

.step-label {
    font-size: 0.75rem;
}

.step-item button {
    border: none;
    background: none;
}

